<?php
require_once 'auth.php';require_role(['super_admin','registrar']);
$message='';$type='error';
if($_SERVER['REQUEST_METHOD']==='POST') {
 $id=(int)($_POST['id']??0);$status=$_POST['status']??'';$response=is_string($_POST['response']??null)?trim($_POST['response']):'';
 if(!verify_csrf()){http_response_code(400);$message='Invalid request.';}
 elseif(!in_array($status,['resolved','rejected'],true)||mb_strlen($response)<10||mb_strlen($response)>2000)$message='Choose a status and provide a response of 10–2000 characters.';
 else {
  $by=$_SESSION['admin_username'];$q=mysqli_prepare($conn,"UPDATE student_result_issues SET status=?,response=?,resolved_by=?,resolved_at=NOW() WHERE id=? AND status='pending'");mysqli_stmt_bind_param($q,'sssi',$status,$response,$by,$id);mysqli_stmt_execute($q);
  if(mysqli_stmt_affected_rows($q)){audit_log($conn,'RESULT_ISSUE_REVIEWED','result_issue',(string)$id,$status);$message='Response saved.';$type='success';}else $message='This request has already been reviewed.';
 }
}
$issues=mysqli_fetch_all(mysqli_query($conn,"SELECT i.*,s.name,s.index_number FROM student_result_issues i JOIN students s ON s.student_id=i.student_id ORDER BY (i.status='pending') DESC,i.id DESC LIMIT 100"),MYSQLI_ASSOC);
?>
<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Result Issues</title><link rel="stylesheet" href="modern-ui.css?v=20261008-student1"></head><body><div class="main-wrapper"><?php include 'admin_nav.php';?><main class="content"><section class="page-heading"><div><span class="page-kicker">Student Support</span><h1>Student Result Issues</h1><p>Latest 100 requests, pending first. Handle academic corrections through the existing reopen and approval workflow.</p></div></section><?php if($message):?><div class="message <?=e($type)?>"><?=e($message)?></div><?php endif;?><?php if(!$issues):?><section class="feature-card"><p>No result issues have been submitted.</p></section><?php endif;?><?php foreach($issues as $issue):?><section class="feature-card student-issue-card"><div><strong>#<?=(int)$issue['id']?> · <?=e($issue['name'])?> · <?=e($issue['index_number'])?></strong><span class="status-pill <?=e($issue['status'])?>"><?=e(ucfirst($issue['status']))?></span></div><small><?=e($issue['student_id'])?> · Year <?=e($issue['year'])?> / Semester <?=e($issue['semester'])?> · <?=e($issue['created_at'])?></small><p><?=nl2br(e($issue['description']))?></p><?php if($issue['status']==='pending'):?><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$issue['id']?>"><label for="response-<?=(int)$issue['id']?>">Response to student</label><textarea id="response-<?=(int)$issue['id']?>" name="response" required minlength="10" maxlength="2000" rows="3"></textarea><label for="status-<?=(int)$issue['id']?>">Decision</label><select id="status-<?=(int)$issue['id']?>" name="status"><option value="resolved">Resolved</option><option value="rejected">Rejected</option></select><div class="button-row"><button type="submit">Save Response</button><a class="btn-link btn-secondary" href="view_results.php?student_id=<?=urlencode($issue['student_id'])?>&amp;year=<?=e($issue['year'])?>&amp;semester=<?=e($issue['semester'])?>">Review Results</a></div></form><?php else:?><div class="issue-response"><p><?=nl2br(e($issue['response']))?></p><small>Reviewed by <?=e($issue['resolved_by'])?> · <?=e($issue['resolved_at'])?></small></div><?php endif;?></section><?php endforeach;?></main><?php include 'footer.php';?></div></body></html>
